import { and, count, desc, eq, gte, or, sql } from 'drizzle-orm';
import { getDb } from '../db/index.js';
import { listings, type ListingRow, type NewListingRow } from '../db/schema.js';
import {
  DUPLICATE_WINDOW_MS,
  LISTING_COOLDOWN_MS,
  LISTING_TTL_MS,
  MY_LISTINGS_PAGE_SIZE,
  SEARCH_PAGE_SIZE,
} from '../utils/constants.js';
import type { Accepts, ListingCreateInput, ListingIntent } from '../types/index.js';

const now = () => Date.now();

export interface CreateListingResult {
  listing: ListingRow;
  warning?: string;
}

function insertListingRow(input: ListingCreateInput, created: number): ListingRow {
  const db = getDb();
  const row: NewListingRow = {
    serverId: input.serverId,
    userId: input.userId,
    username: input.username,
    intent: input.intent,
    accepts: input.accepts,
    game: input.game ?? 'mtg',
    cardName: input.cardName,
    cardNameNormalized: input.cardNameNormalized,
    cardSet: input.cardSet ?? null,
    cardImageUrl: input.cardImageUrl ?? null,
    finish: input.finish ?? null,
    variant: input.variant ?? null,
    collectorNumber: input.collectorNumber ?? null,
    manapoolUrl: input.manapoolUrl ?? null,
    condition: input.condition ?? null,
    priceCents: input.priceCents ?? null,
    kind: input.kind ?? 'card',
    sealedUuid: input.sealedUuid ?? null,
    sealedCategory: input.sealedCategory ?? null,
    sealedSubtype: input.sealedSubtype ?? null,
    quantity: input.quantity ?? 1,
    notes: input.notes ?? null,
    status: 'active',
    expiresAt: created + LISTING_TTL_MS,
    createdAt: created,
    updatedAt: created,
  };
  return db.insert(listings).values(row).returning().get();

