  const current = await db.select().from(listings).where(eq(listings.id, id)).run();
  if (current.length === 0) return;
  const currentStatus = current[0].status;
  if (['fulfilled', 'deleted', 'expired'].includes(currentStatus)) {
    return;
  }
  await db.update(listings).set({ status, updatedAt: now() }).where(eq(listings.id, id)).run();
}

test('should not allow status transition after terminal state', async () => {
  const listing = await db.insert(listings).values({
    id: 1,
    status: 'active',
    createdAt: new Date(),
    updatedAt: new Date()
  }).run();

  // Soft delete first
  await softDeleteListing(1);
  const deleted = await db.select().from(listings).where(eq(listings.id, 1)).run();
  expect(deleted[0].status).toBe('deleted');

  // Then try to fulfill
  await fulfillListing(1);
  const final = await db.select().from(listings).where(eq(listings.id, 1)).run();
  expect(final[0].status).toBe('deleted');
});

